<div class="section-head"><div><span class="eyebrow">VEHICLE TEMPLATES</span><h1>Template รถ</h1><p>เก็บตารางรถของแต่ละ land ไว้ดึงไปใช้ตอนลงโปรแกรม</p></div><a class="btn" href="<?= base_url().'admin/vehicle-templates/new' ?>">＋ เพิ่ม template</a></div>
<p class="notice">โปรแกรมจะคัดลอกตารางไปตอนดึงใช้ การแก้หรือลบ template ที่นี่จึงไม่เปลี่ยนโปรแกรมที่ลงไปแล้ว</p>
<div class="panel table-scroll"><table><thead><tr><th>ชื่อ template</th><th>รถ</th><th>รูปรถจริง</th><th>จัดการ</th></tr></thead><tbody>
<?php foreach ($templates as $template): $templateRows=\App\Support\VehicleOptions::decode($template['vehicle_rows']); ?><tr><td><b><?= e($template['name']) ?></b></td><td><?php foreach ($templateRows as $row): ?><div><?= people_range($row['min'],$row['max']) ?> คน · <?= e(\App\Support\VehicleOptions::label($row)) ?></div><?php endforeach ?></td><td><?= count(\App\Support\VehicleOptions::images($templateRows)) ?> / <?= count($templateRows) ?></td><td><a class="text-link" href="<?= base_url().'admin/vehicle-templates/'.(int)$template['id'] ?>">แก้ไข</a><form method="post" action="<?= base_url().'admin/vehicle-templates/'.(int)$template['id'].'/delete' ?>" onsubmit="return confirm('ลบ template นี้? โปรแกรมที่ดึงไปใช้แล้วจะไม่เปลี่ยน')"><?= csrf_field() ?><button class="text-button danger" type="submit">ลบ</button></form></td></tr><?php endforeach ?>
<?php if (!$templates): ?><tr><td colspan="4">ยังไม่มี template กด “เพิ่ม template” หรือกดบันทึกจากหน้าแก้ไขโปรแกรม</td></tr><?php endif ?></tbody></table></div>
